<script>
(function(){
  var wiz = document.currentScript.previousElementSibling;
  if (!wiz || !wiz.classList || !wiz.classList.contains('hacwiz')) {
    wiz = document.querySelector('.hacwiz');
  }
  if (!wiz) return;
  var selectedService = '';

  function val(id) { var el = document.getElementById(id); return el ? el.value.trim() : ''; }

  function showStep(n) {
    var steps = wiz.querySelectorAll('.hacwiz-step');
    for (var i = 0; i < steps.length; i++) {
      steps[i].style.display = (steps[i].getAttribute('data-step') === String(n)) ? 'block' : 'none';
    }
    var dots = wiz.querySelectorAll('.hacwiz-dot-wrap');
    for (var j = 0; j < dots.length; j++) {
      var dotStep = parseInt(dots[j].getAttribute('data-step'), 10);
      var dot = dots[j].querySelector('.hacwiz-dot');
      if (dotStep <= n) { dot.style.background = '#F86810'; dot.style.color = '#fff'; }
      else { dot.style.background = '#E4E1D8'; dot.style.color = '#5C6B6D'; }
    }
    if (n === 4) { buildSummary(); }
  }

  function buildSummary() {
    var propertyType = val('hacwiz-property-type') || 'Not specified';
    var street = val('hacwiz-street') || 'Not provided';
    var postcode = val('hacwiz-postcode') || 'Not provided';
    var brand = val('hacwiz-brand') || 'Not specified';
    var model = val('hacwiz-model') || 'Not provided';
    var warranty = val('hacwiz-warranty') || 'Not specified';
    var retailer = val('hacwiz-retailer') || 'Not provided';
    var firstName = val('hacwiz-first-name');
    var lastName = val('hacwiz-last-name');
    var name = (firstName + ' ' + lastName).trim() || 'Not provided';
    var phone = val('hacwiz-phone') || 'Not provided';
    var email = val('hacwiz-email') || 'Not provided';
    var time = val('hacwiz-time') || 'Not specified';
    var onsiteName = val('hacwiz-onsite-name');
    var onsitePhone = val('hacwiz-onsite-phone');
    var description = val('hacwiz-description') || 'None provided';

    var summary = wiz.querySelector('#hacwiz-summary');
    summary.innerHTML = '';
    var rows = [
      ['Property', propertyType], ['Address', street + ', ' + postcode],
      ['Appliance', selectedService || 'Not selected'], ['Brand / Model', brand + (model !== 'Not provided' ? ' - ' + model : '')],
      ['Warranty claim', warranty], ['Retailer', retailer],
      ['Name', name], ['Phone', phone], ['Email', email], ['Preferred time', time],
      ['Problem', description]
    ];
    if (onsiteName || onsitePhone) {
      rows.push(['Onsite contact', (onsiteName || 'Not named') + ' - ' + (onsitePhone || 'no phone given')]);
    }
    for (var k = 0; k < rows.length; k++) {
      var p = document.createElement('p');
      p.style.margin = '0 0 4px 0';
      var strong = document.createElement('strong');
      strong.textContent = rows[k][0] + ': ';
      p.appendChild(strong);
      p.appendChild(document.createTextNode(rows[k][1]));
      summary.appendChild(p);
    }
  }

  var nextBtns = wiz.querySelectorAll('.hacwiz-next');
  for (var a = 0; a < nextBtns.length; a++) { nextBtns[a].addEventListener('click', function(){ showStep(this.getAttribute('data-goto')); }); }
  var backBtns = wiz.querySelectorAll('.hacwiz-back');
  for (var b = 0; b < backBtns.length; b++) { backBtns[b].addEventListener('click', function(){ showStep(this.getAttribute('data-goto')); }); }
  var svcBtns = wiz.querySelectorAll('.hacwiz-svc');
  for (var c = 0; c < svcBtns.length; c++) {
    svcBtns[c].addEventListener('click', function(){
      for (var d = 0; d < svcBtns.length; d++) { svcBtns[d].style.borderColor = '#E4E1D8'; svcBtns[d].style.background = '#FBF8F3'; }
      this.style.borderColor = '#F86810'; this.style.background = '#FFF1EC';
      selectedService = this.getAttribute('data-svc');
    });
  }

  function buildMailto(payload) {
    var subject = 'Booking Request: ' + (payload.service || 'Appliance Repair');
    var lines = [
      'Property: ' + payload.property_type, 'Address: ' + payload.street_address + ', ' + payload.suburb,
      'Appliance: ' + payload.service, 'Brand: ' + payload.brand, 'Model: ' + payload.model,
      'Warranty claim: ' + payload.warranty, 'Retailer: ' + payload.retailer,
      'Name: ' + payload.first_name + ' ' + payload.last_name, 'Phone: ' + payload.phone, 'Email: ' + payload.email,
      'Preferred time: ' + payload.time, 'Onsite contact: ' + payload.onsite_name + ' ' + payload.onsite_phone,
      'Problem: ' + payload.description
    ];
    return 'mailto:bookings@hobartappliancecare.com?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(lines.join('\n'));
  }

  var submitBtn = wiz.querySelector('#hacwiz-submit');
  var statusEl = wiz.querySelector('#hacwiz-status');
  if (submitBtn) {
    submitBtn.addEventListener('click', function(){
      var payload = {
        property_type: val('hacwiz-property-type'), street_address: val('hacwiz-street'), suburb: val('hacwiz-postcode'),
        service: selectedService, brand: val('hacwiz-brand'), model: val('hacwiz-model'),
        warranty: val('hacwiz-warranty'), retailer: val('hacwiz-retailer'),
        first_name: val('hacwiz-first-name'), last_name: val('hacwiz-last-name'),
        phone: val('hacwiz-phone'), email: val('hacwiz-email'), time: val('hacwiz-time'),
        onsite_name: val('hacwiz-onsite-name'), onsite_phone: val('hacwiz-onsite-phone'),
        description: val('hacwiz-description'), website: val('hacwiz-website')
      };
      var fullName = (payload.first_name + ' ' + payload.last_name).trim();

      if (!fullName || (!payload.phone && !payload.email)) {
        if (statusEl) { statusEl.textContent = 'Please add your name and a phone number or email so we can reach you.'; statusEl.style.color = '#F86810'; }
        return;
      }

      submitBtn.disabled = true;
      submitBtn.style.opacity = '0.7';
      submitBtn.textContent = 'Sending…';
      if (statusEl) { statusEl.textContent = ''; }

      fetch('/wp-json/hac/v1/book', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      }).then(function(res){
        return res.json().then(function(data){ return { ok: res.ok, data: data }; });
      }).then(function(result){
        if (result.ok && result.data && result.data.success) {
          wiz.innerHTML = '<div style="text-align:center;padding:20px 0;"><div style="font-size:40px;margin-bottom:12px;">✅</div><h3 style="color:#021131;margin:0 0 8px 0;">Booking request sent!</h3><p style="color:#5C6B6D;font-size:14.5px;margin:0 0 18px 0;">A local technician will call you shortly to confirm. Urgent? Call us on <a href="mailto:bookings@hobartappliancecare.com" style="color:#0E7C7B;font-weight:700;text-decoration:none;">bookings@hobartappliancecare.com</a>.</p></div>';
        } else {
          submitBtn.disabled = false;
          submitBtn.style.opacity = '1';
          submitBtn.textContent = 'Send Booking Request';
          if (statusEl) { statusEl.textContent = (result.data && result.data.message) || "Couldn't send automatically — opening your email app instead."; statusEl.style.color = '#F86810'; }
          window.location.href = buildMailto(payload);
        }
      }).catch(function(){
        submitBtn.disabled = false;
        submitBtn.style.opacity = '1';
        submitBtn.textContent = 'Send Booking Request';
        if (statusEl) { statusEl.textContent = "Couldn't reach our server — opening your email app instead."; statusEl.style.color = '#F86810'; }
        window.location.href = buildMailto(payload);
      });
    });
  }
})();
