<script>
(function(){
  function init(){
    var roots = document.querySelectorAll('.elementor');
    var targets = [];
    roots.forEach(function(root){
      var kids = root.children;
      for (var i=0;i<kids.length;i++){
        var el = kids[i];
        if (!el.classList || !el.classList.contains('e-con')) continue;
        if (el.querySelector('#hac-hb-btn')) continue;
        var rect = el.getBoundingClientRect();
        if (rect.top < window.innerHeight * 1.15) { continue; }
        el.classList.add('hac-reveal');
        targets.push(el);
      }
    });
    targets.forEach(function(el,i){ el.style.transitionDelay = ((i % 4) * 0.07) + 's'; });
    if ('IntersectionObserver' in window) {
      var io = new IntersectionObserver(function(entries){
        entries.forEach(function(entry){
          if (entry.isIntersecting) { entry.target.classList.add('hac-in-view'); io.unobserve(entry.target); }
        });
      }, {threshold:0.1, rootMargin:'0px 0px -30px 0px'});
      targets.forEach(function(el){ io.observe(el); });
    } else {
      targets.forEach(function(el){ el.classList.add('hac-in-view'); });
    }
  }
  function fixA11y(){
    document.querySelectorAll('[role="button"]:not([tabindex])').forEach(function(el){
