  function fixHeadingOrder(){
    var headings = Array.prototype.slice.call(document.querySelectorAll('h1,h2,h3,h4,h5,h6'));
    var prevLevel = 0;
    headings.forEach(function(h){
      var level = parseInt(h.tagName.substring(1), 10);
      if (prevLevel > 0 && level > prevLevel + 1) { level = prevLevel + 1; }
      if (level !== parseInt(h.tagName.substring(1), 10)) {
        var nh = document.createElement('h' + level);
        for (var i = 0; i < h.attributes.length; i++) { nh.setAttribute(h.attributes[i].name, h.attributes[i].value); }
        while (h.firstChild) { nh.appendChild(h.firstChild); }
        h.parentNode.replaceChild(nh, h);
        h = nh;
      }
      prevLevel = level;
    });
  }
  function fixDuplicateLinkNames(){
