      if (!t) return;
      (groups[t] = groups[t] || []).push(a);
    });
    Object.keys(groups).forEach(function(t){
      var arr = groups[t];
      var hrefSet = {};
      arr.forEach(function(a){ hrefSet[a.getAttribute('href') || ''] = 1; });
      if (Object.keys(hrefSet).length <= 1) return;
      arr.forEach(function(a){
        if (a.hasAttribute('aria-label')) return;
        var href = a.getAttribute('href') || '';
        var slug = href.replace(/^\/|\/$/g, '').split('/').pop();
        var name = slugNames[slug];
        if (name) { a.setAttribute('aria-label', t.replace(/[→]/g, '').trim() + ' – ' + name); }
      });
    });
  }
  function fixTabAria(){
    function clean(el){
      if (el.getAttribute && el.getAttribute('role') === 'button' && el.hasAttribute('aria-selected')) {
        el.removeAttribute('aria-selected');
      }
    }
    document.querySelectorAll('[role="button"][aria-selected]').forEach(clean);
